const { data, error } = await dashboardSupabase.auth.signUp({
email,
password,
options: {
data: {
first_name: firstName,
last_name: lastName,
full_name: `${firstName} ${lastName}`
},
emailRedirectTo: "https://baggle.net/dashboard/"
}
});
if (error) {
authErrorEl.textContent = error.message;
return;
}
