let alertsFeed = [];
let alertsFilter = "all";
function priceParts(str) {
const m = String(str || "").match(/^[^\d\s.,-]+/);
return { n: BaggleData.parsePriceNumber(str), sym: m ? m[0] : "" };
}
function priceDropInfo(alert) {
const o = priceParts(alert.old_price);
const n = priceParts(alert.new_price);
if (o.n == null || n.n == null) return { show: true };
const diff = o.n - n.n;
if (diff <= 0) return { show: false };
const pct = (diff / o.n) * 100;
return { show: diff >= 0.5 || pct >= 2, diff, pct, sym: n.sym || o.sym };
}
function alertDayGroup(iso) {
const d = new Date(iso);
const startOf = (x) => new Date(x.getFullYear(), x.getMonth(), x.getDate()).getTime();
const days = Math.round((startOf(new Date()) - startOf(d)) / 86400000);
if (days <= 0) return "Today";
if (days === 1) return "Yesterday";
if (days < 7) return "Earlier this week";
return "Earlier";
}
const ALERT_HEART = '<svg viewBox="0 0 24 24"><path d="M12 20s-7-4.35-9.5-9A5.5 5.5 0 0 1 12 6a5.5 5.5 0 0 1 9.5 5c-2.5 4.65-9.5 9-9.5 9Z"/></svg>';
const ALERT_PERSON = '<svg viewBox="0 0 24 24"><circle cx="12" cy="8.5" r="3.6"/><path d="M5 20c.6-3.8 3.3-5.9 7-5.9s6.4 2.1 7 5.9"/></svg>';
const ALERT_EMPTY_TEXT = {
all: "Nothing here yet. When something you've saved drops in price or sells out, or someone follows or likes one of your bags, you'll see it here.",
price: "No price drops yet. We'll tell you when something you've saved gets cheaper.",
stock: "Nothing sold out. We'll tell you if something you've saved sells out.",
activity: "No activity yet. Follows and likes on your bags will show up here."
};
function alertRowHtml(alert) {
const esc = BaggleData.escapeHtml;
if (alert.kind === "follow" || alert.kind === "like") {
const who = alert.person || {};
const name = who.display_name || "Someone";
const verb = alert.kind === "follow" ? "followed" : "liked";
const icon = alert.kind === "follow" ? ALERT_PERSON : ALERT_HEART;
return `
<div class="alert-card activity" data-key="${esc(alert.key)}">
<div class="alert-avatar">${miniAvatarHtml(who.avatar_url || null, name, true)}<span class="alert-kind ${alert.kind}">${icon}</span></div>
<div class="alert-main">
<div class="alert-text"><strong>${esc(name)}</strong> ${verb} <button type="button" class="alert-bag-link" data-bag-id="${esc(alert.bag_id)}">${esc(alert.bagName || "your bag")}</button></div>
</div>
</div>`;
}
const item = alert.items || {};
const title = item.title || "A saved item";
const bagName = item.bags && (Array.isArray(item.bags) ? item.bags[0]?.name : item.bags.name);
const sub = [item.site, bagName].filter(Boolean).join(" · ");
let priceHtml;
if (alert.kind === "stock") {
priceHtml = `<span class="alert-badge out">Sold out</span>`;
} else {
const info = priceDropInfo(alert);
const badge = info.diff
? `<span class="alert-badge drop">−${esc(info.sym)}${info.diff.toFixed(2)} · ${Math.round(info.pct)}% off</span>`
: "";
priceHtml = `<span class="alert-now">${esc(alert.new_price || "")}</span>${alert.old_price ? `<span class="alert-was">${esc(alert.old_price)}</span>` : ""}${badge}`;
}
return `
<div class="alert-card" data-key="${esc(alert.key)}">
${item.image ? `<img class="alert-thumb" src="${esc(item.image)}" alt="">` : `<div class="alert-thumb"></div>`}
<div class="alert-main">
${sub ? `<div class="alert-sub">${esc(sub)}</div>` : ""}
<div class="alert-text name">${esc(title)}</div>
<div class="alert-price">${priceHtml}</div>
</div>
<div class="alert-actions">
${item.url ? `<button type="button" class="btn-pill solid alert-go" data-url="${esc(item.url)}">Go to store</button>` : ""}
<button type="button" class="remove" title="Delete alert" aria-label="Delete alert">✕</button>
</div>
</div>`;
}
function drawAlerts() {
const wrap = document.getElementById("alertsList");
const list = alertsFeed.filter((a) => {
if (alertsFilter === "all") return true;
if (alertsFilter === "activity") return a.kind === "follow" || a.kind === "like";
return a.kind === alertsFilter;
});
if (list.length === 0) {
wrap.innerHTML = `<div class="alerts-empty"><div class="alerts-empty-icon"><svg viewBox="0 0 24 24"><path d="M6 10.5a6 6 0 0 1 12 0c0 4 1.5 5.3 1.5 5.3H4.5S6 14.5 6 10.5Z"/><path d="M10 19a2.2 2.2 0 0 0 4 0"/></svg></div><p>${BaggleData.escapeHtml(ALERT_EMPTY_TEXT[alertsFilter])}</p></div>`;
return;
}
let html = "";
let lastGroup = null;
list.forEach((a) => {
const group = alertDayGroup(a.created_at);
if (group !== lastGroup) {
html += `<h2 class="alerts-day">${group}</h2>`;
lastGroup = group;
}
html += alertRowHtml(a);
});
wrap.innerHTML = html;
wrap.querySelectorAll(".alert-go").forEach((btn) => {
btn.addEventListener("click", () => openExternal(btn.dataset.url));
});
wrap.querySelectorAll(".alert-bag-link").forEach((btn) => {
btn.addEventListener("click", () => {
document.querySelectorAll(".side-btn[data-nav]").forEach((b) => b.classList.toggle("active", b.dataset.nav === "home"));
openBag(btn.dataset.bagId);
});
});
wrap.querySelectorAll(".alert-card .remove").forEach((btn) => {
btn.addEventListener("click", async () => {
const card = btn.closest(".alert-card");
const alert = alertsFeed.find((x) => x.key === card.dataset.key);
if (!alert) return;
btn.disabled = true;
const table = alert.kind === "stock" ? "stock_alerts" : "price_alerts";
const { error } = await dashboardSupabase.from(table).delete().eq("id", alert.id);
if (error) {
console.error(`Failed to delete ${alert.kind} alert`, error);
btn.disabled = false;
flashToast("Couldn't delete that — try again.");
return;
}
alertsFeed = alertsFeed.filter((x) => x.key !== alert.key);
drawAlerts();
});
});
}
document.getElementById("alertsTabs").addEventListener("click", (e) => {
const tab = e.target.closest(".filter-tab");
if (!tab) return;
alertsFilter = tab.dataset.filter;
document.querySelectorAll("#alertsTabs .filter-tab").forEach((t) => {
const on = t === tab;
t.classList.toggle("active", on);
t.setAttribute("aria-selected", String(on));
});
drawAlerts();
});
async function renderAlertsList() {
const wrap = document.getElementById("alertsList");
wrap.innerHTML = `<div class="empty-alerts">Loading…</div>`;
async function loadAlertRows(table, withExtras, extraCols) {
const select = withExtras
? `id, ${extraCols}created_at, items(title, image, url, site, bags(name))`
: `id, ${extraCols}created_at, items(title, image, url)`;
return dashboardSupabase.from(table).select(select).eq("user_id", currentUser.id).order("created_at", { ascending: false }).limit(50);
}
async function loadWithFallback(table, extraCols) {
const rich = await loadAlertRows(table, true, extraCols);
if (!rich.error) return rich;
console.error(`Rich ${table} query failed, retrying plain`, rich.error);
return loadAlertRows(table, false, extraCols);
}
const bagIds = state.order;
const bagNameById = {};
bagIds.forEach((id) => { bagNameById[id] = state.bags[id].name; });
const noRows = Promise.resolve({ data: [], error: null });
const [priceResult, stockResult, followsResult, likesResult] = await Promise.all([
loadWithFallback("price_alerts", "old_price, new_price, "),
loadWithFallback("stock_alerts", ""),
bagIds.length ? dashboardSupabase.from("bag_follows").select("bag_id, follower_id, created_at").in("bag_id", bagIds).order("created_at", { ascending: false }).limit(25) : noRows,
bagIds.length ? dashboardSupabase.from("bag_likes").select("bag_id, user_id, created_at").in("bag_id", bagIds).order("created_at", { ascending: false }).limit(25) : noRows
]);
if (priceResult.error) console.error("Failed to load price alerts", priceResult.error);
if (stockResult.error) console.error("Failed to load stock alerts", stockResult.error);
if (followsResult.error) console.error("Failed to load follow activity", followsResult.error);
if (likesResult.error) console.error("Failed to load like activity", likesResult.error);
if (priceResult.error && stockResult.error) {
wrap.innerHTML = `<div class="empty-alerts">Couldn't load your alerts — try again.</div>`;
return;
}
const follows = (followsResult.data || []).filter((f) => f.follower_id !== currentUser.id);
const likes = (likesResult.data || []).filter((l) => l.user_id !== currentUser.id);
const peopleIds = Array.from(new Set([...follows.map((f) => f.follower_id), ...likes.map((l) => l.user_id)]));
const people = {};
if (peopleIds.length) {
const { data: profiles, error: profErr } = await dashboardSupabase.from("profiles").select("user_id, display_name, avatar_url").in("user_id", peopleIds);
if (profErr) console.error("Failed to load people for activity", profErr);
(profiles || []).forEach((p) => { people[p.user_id] = p; });
}
alertsFeed = [
...(priceResult.data || []).filter((a) => priceDropInfo(a).show).map((a) => ({ ...a, kind: "price", key: `p-${a.id}` })),
...(stockResult.data || []).map((a) => ({ ...a, kind: "stock", key: `s-${a.id}` })),
...follows.map((f) => ({ kind: "follow", key: `f-${f.bag_id}-${f.follower_id}`, bag_id: f.bag_id, bagName: bagNameById[f.bag_id], created_at: f.created_at, person: people[f.follower_id] })),
...likes.map((l) => ({ kind: "like", key: `l-${l.bag_id}-${l.user_id}`, bag_id: l.bag_id, bagName: bagNameById[l.bag_id], created_at: l.created_at, person: people[l.user_id] }))
].sort((a, b) => new Date(b.created_at) - new Date(a.created_at));
drawAlerts();
}
const swatchIcon = '<svg viewBox="0 0 24 24"><path d="M8 4h8l2 3-3 2v11H9V9L6 7Z"/></svg>';
function bagCollageHtml(bag) {
const withImages = bag.items.filter((it) => it.image);
const main = withImages[0];
const secondA = bag.items[1];
const secondB = bag.items[2];
function tile(item, extraClass) {
if (item && item.image) {
return `<div class="tile ${extraClass}"><img src="${BaggleData.escapeHtml(item.image)}" alt=""></div>`;
}
return `<div class="tile ${extraClass}"><div class="swatch" style="background:var(--purple-soft)">${swatchIcon}</div></div>`;
}
if (bag.items.length === 0) {
return `<div class="tile tile-main"><div class="swatch" style="background:var(--cream)">${swatchIcon}</div></div>`;
}
return tile(main || bag.items[0], "tile-main") + tile(secondA, "") + tile(secondB, "");
}
let profileStats = null;
let ownLikeCounts = {};
