function openMoveItemModal(itemId) {
moveItemError.textContent = "";
const otherBagIds = state.order.filter((id) => id !== openBagId);
if (otherBagIds.length === 0) {
bagPickerList.innerHTML = `<div class="bag-picker-empty">You don't have any other bags yet.</div>`;
} else {
bagPickerList.innerHTML = otherBagIds.map((bagId) => {
const bag = state.bags[bagId];
return `
<button class="bag-picker-item" data-bag-id="${bagId}">
<span>${BaggleData.escapeHtml(bag.name)}</span>
<span class="bag-picker-count">${bag.items.length} item${bag.items.length === 1 ? "" : "s"}</span>
</button>`;
}).join("");
bagPickerList.querySelectorAll(".bag-picker-item").forEach((btn) => {
btn.addEventListener("click", () => moveItemToBag(itemId, btn.dataset.bagId));
});
}
moveItemBackdrop.hidden = false;
}
function closeMoveItemModal() {
moveItemBackdrop.hidden = true;
}
moveItemCancelBtn.addEventListener("click", closeMoveItemModal);
moveItemBackdrop.addEventListener("click", (e) => {
if (e.target === moveItemBackdrop) closeMoveItemModal();
});
async function moveItemToBag(itemId, targetBagId) {
const fromBag = state.bags[openBagId];
const item = fromBag?.items.find((i) => i.id === itemId);
if (!item) return;
bagPickerList.querySelectorAll(".bag-picker-item").forEach((btn) => (btn.disabled = true));
const { error } = await BaggleData.moveItem(dashboardSupabase, itemId, targetBagId);
if (error) {
console.error("Failed to move item", error);
moveItemError.textContent = "Couldn't move that — try again.";
bagPickerList.querySelectorAll(".bag-picker-item").forEach((btn) => (btn.disabled = false));
return;
}
fromBag.items = fromBag.items.filter((i) => i.id !== itemId);
state.bags[targetBagId].items.unshift(item);
closeMoveItemModal();
renderBagDetail();
flashToast(`Moved "${item.title}" to "${state.bags[targetBagId].name}"`);
}
bagPrivateCheckbox.addEventListener("change", async (e) => {
const bag = state.bags[openBagId];
if (!bag) return;
const checked = e.target.checked;
e.target.disabled = true;
const { error } = await BaggleData.setBagPrivacy(dashboardSupabase, openBagId, checked);
e.target.disabled = false;
if (error) {
console.error("Failed to update bag privacy", error);
e.target.checked = !checked;
flashToast("Couldn't update that — try again.");
return;
}
bag.isPrivate = checked;
flashToast(checked ? `"${bag.name}" is now private.` : `"${bag.name}" can now be shared.`);
});
function buildShareLink(bagId) {
return `${window.location.origin}${window.location.pathname}?shared=${encodeURIComponent(bagId)}`;
}
function renderSharePrivacyNote(bag) {
if (!currentProfile.isPublic) {
sharePrivacyNote.hidden = false;
sharePrivacyNote.innerHTML = `
<p>Your account is private, so only you can open this link right now.</p>
<label class="checkbox-row"><input type="checkbox" id="shareMakePublicCheckbox"><span>Make my account public</span></label>`;
document.getElementById("shareMakePublicCheckbox").addEventListener("change", async (e) => {
const checked = e.target.checked;
e.target.disabled = true;
const { error } = await BaggleData.setProfilePublic(dashboardSupabase, currentUser.id, checked);
e.target.disabled = false;
if (error) {
console.error("Failed to update account privacy", error);
e.target.checked = !checked;
flashToast("Couldn't update that — try again.");
return;
}
currentProfile.isPublic = checked;
updateBagPrivateRowVisibility();
renderSharePrivacyNote(bag);
});
} else if (bag.isPrivate) {
sharePrivacyNote.hidden = false;
sharePrivacyNote.innerHTML = `
<p>This bag is marked private, so only you can open this link right now.</p>
<label class="checkbox-row"><input type="checkbox" id="shareMakeBagPublicCheckbox"><span>Make this bag shareable</span></label>`;
document.getElementById("shareMakeBagPublicCheckbox").addEventListener("change", async (e) => {
const checked = e.target.checked;
e.target.disabled = true;
const { error } = await BaggleData.setBagPrivacy(dashboardSupabase, openBagId, !checked);
e.target.disabled = false;
if (error) {
console.error("Failed to update bag privacy", error);
e.target.checked = !checked;
flashToast("Couldn't update that — try again.");
return;
}
bag.isPrivate = !checked;
bagPrivateCheckbox.checked = bag.isPrivate;
renderSharePrivacyNote(bag);
});
} else {
sharePrivacyNote.hidden = true;
sharePrivacyNote.innerHTML = "";
}
}
function openShareModal() {
const bag = state.bags[openBagId];
if (!bag) return;
shareLinkInput.value = buildShareLink(openBagId);
renderSharePrivacyNote(bag);
shareBackdrop.hidden = false;
}
function closeShareModal() {
shareBackdrop.hidden = true;
}
shareBagBtn.addEventListener("click", openShareModal);
shareCloseBtn.addEventListener("click", closeShareModal);
shareBackdrop.addEventListener("click", (e) => {
if (e.target === shareBackdrop) closeShareModal();
});
shareCopyBtn.addEventListener("click", async () => {
try {
await navigator.clipboard.writeText(shareLinkInput.value);
flashToast("Link copied.");
} catch (err) {
console.error("Failed to copy link", err);
shareLinkInput.focus();
shareLinkInput.select();
flashToast("Couldn't copy automatically — the link is selected, press Cmd/Ctrl+C.");
}
});
function renderEngagementList(listEl, countEl, people, emptyLabel) {
countEl.textContent = String(people.length);
if (people.length === 0) {
listEl.innerHTML = `<div class="engagement-empty">${emptyLabel}</div>`;
return;
}
listEl.innerHTML = people
.map((p) => `<div class="engagement-row">${miniAvatarHtml(p.avatar, p.name, true)}<span>${BaggleData.escapeHtml(p.name)}</span></div>`)
.join("");
}
async function openEngagementModal() {
const bag = state.bags[openBagId];
if (!bag) return;
engagementBackdrop.hidden = false;
renderEngagementList(engagementFollowList, engagementFollowCount, [], "Loading…");
renderEngagementList(engagementLikeList, engagementLikeCount, [], "Loading…");
const { data, error } = await BaggleData.loadBagEngagement(dashboardSupabase, openBagId);
if (error) {
console.error("Failed to load followers/likes", error);
renderEngagementList(engagementFollowList, engagementFollowCount, [], "Couldn't load this — try again.");
renderEngagementList(engagementLikeList, engagementLikeCount, [], "Couldn't load this — try again.");
return;
}
renderEngagementList(engagementFollowList, engagementFollowCount, data.followers, "No one yet.");
renderEngagementList(engagementLikeList, engagementLikeCount, data.likers, "No one yet.");
}
function closeEngagementModal() {
engagementBackdrop.hidden = true;
}
if (engagementBtn && engagementCloseBtn && engagementBackdrop) {
engagementBtn.addEventListener("click", openEngagementModal);
engagementCloseBtn.addEventListener("click", closeEngagementModal);
engagementBackdrop.addEventListener("click", (e) => {
if (e.target === engagementBackdrop) closeEngagementModal();
});
}
let bagModalRenameId = null;
function openCreateBagModal() {
bagModalRenameId = null;
document.getElementById("bagModalTitle").textContent = "Name your bag";
modalCreateBtn.textContent = "Create";
newBagNameInput.value = "";
modalError.textContent = "";
modalBackdrop.hidden = false;
newBagNameInput.focus();
}
function openRenameBagModal(bagId) {
const bag = state.bags[bagId];
if (!bag) return;
bagModalRenameId = bagId;
document.getElementById("bagModalTitle").textContent = "Rename bag";
modalCreateBtn.textContent = "Save";
newBagNameInput.value = bag.name;
modalError.textContent = "";
modalBackdrop.hidden = false;
newBagNameInput.focus();
newBagNameInput.select();
}
function closeCreateBagModal() {
modalBackdrop.hidden = true;
}
document.getElementById("newBagSideBtn").addEventListener("click", openCreateBagModal);
modalCancelBtn.addEventListener("click", closeCreateBagModal);
modalBackdrop.addEventListener("click", (e) => {
if (e.target === modalBackdrop) closeCreateBagModal();
});
newBagNameInput.addEventListener("keydown", (e) => {
if (e.key === "Enter") modalCreateBtn.click();
if (e.key === "Escape") closeCreateBagModal();
});
modalCreateBtn.addEventListener("click", async () => {
const name = newBagNameInput.value.trim();
if (!name) {
modalError.textContent = "Give your bag a name.";
return;
}
if (bagModalRenameId) {
const bagId = bagModalRenameId;
if (state.bags[bagId] && state.bags[bagId].name === name) {
closeCreateBagModal();
return;
}
modalCreateBtn.disabled = true;
const { error: renameErr } = await BaggleData.renameBag(dashboardSupabase, bagId, name);
modalCreateBtn.disabled = false;
if (renameErr) {
console.error("Failed to rename bag", renameErr);
modalError.textContent = "Couldn't rename that bag — try again.";
return;
}
if (state.bags[bagId]) state.bags[bagId].name = name;
closeCreateBagModal();
renderHome();
refreshOwnLikeCounts();
flashToast(`Renamed to "${name}"`);
return;
}
modalCreateBtn.disabled = true;
const { data, error } = await BaggleData.createBag(dashboardSupabase, currentUser.id, name);
modalCreateBtn.disabled = false;
if (error) {
console.error("Failed to create bag", error);
modalError.textContent = "Couldn't create that bag — try again.";
return;
}
state.bags[data.id] = data;
state.order.push(data.id);
closeCreateBagModal();
const profileNav = document.querySelector('.side-btn[data-nav="home"]');
if (profileNav) profileNav.click(); else goHome();
flashToast(`Created "${data.name}"`);
});
